using BetaFit.Desktop.Models;using BetaFit.Desktop.Services;using System.Globalization;
namespace BetaFit.Desktop.Forms;
public sealed class FrmProductForm:Form {private readonly IBetaFitApiService _api;private readonly Guid? _id;private readonly TextBox name=new(),desc=new(),price=new(),image=new();private readonly ComboBox category=new(),gender=new();private readonly CheckBox featured=new();public FrmProductForm(IBetaFitApiService api,Guid? id){_api=api;_id=id;Text=id.HasValue?"Editar produto":"Novo produto";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(540,570);BackColor=Color.FromArgb(15,18,23);name.PlaceholderText="Nome";desc.PlaceholderText="Descrição";desc.Multiline=true;desc.Height=90;price.PlaceholderText="Preço";image.PlaceholderText="Imagem URL";category.DropDownStyle=ComboBoxStyle.DropDownList;gender.DropDownStyle=ComboBoxStyle.DropDownList;gender.Items.AddRange(new object[]{"Unissex","Masculino","Feminino"});gender.SelectedIndex=0;featured.Text="Produto em destaque";featured.ForeColor=Color.White;var save=new Button{Text="Salvar",Width=110,Height=40};var cancel=new Button{Text="Cancelar",Width=110,Height=40};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(35),FlowDirection=FlowDirection.TopDown,WrapContents=false};foreach(var c in new Control[]{name,desc,price,image,category,gender,featured,save,cancel}){c.Width=450;c.Margin=new Padding(0,0,0,12);flow.Controls.Add(c);}Controls.Add(flow);cancel.Click+=(_,_)=>Close();save.Click+=async(_,_)=>await SaveAsync();Load+=async(_,_)=>await LoadAsync();}private async Task LoadAsync(){try{var cs=await _api.GetCategoriesAsync(true);category.DataSource=cs.ToList();category.DisplayMember="Name";category.ValueMember="Id";if(_id.HasValue){var r=await _api.SearchProductsAsync(null,null,1,100);var p=r.Items.FirstOrDefault(x=>x.Id==_id);if(p!=null){name.Text=p.Name;price.Text=p.Price.ToString(CultureInfo.InvariantCulture);featured.Checked=p.IsFeatured;gender.SelectedIndex=p.Gender;category.SelectedValue=cs.FirstOrDefault(x=>x.Name==p.CategoryName)?.Id;}}}catch(Exception ex){MessageBox.Show(ex.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}private async Task SaveAsync(){if(string.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Nome obrigatório.");return;}if(!decimal.TryParse(price.Text.Replace(",","."),NumberStyles.Any,CultureInfo.InvariantCulture,out var p)||p<=0){MessageBox.Show("Preço deve ser maior que zero.");return;}if(category.SelectedValue is not Guid cid||cid==Guid.Empty){MessageBox.Show("Categoria obrigatória.");return;}try{if(_id.HasValue)await _api.UpdateProductAsync(_id.Value,new UpdateProductRequest{Name=name.Text.Trim(),Description=desc.Text.Trim(),Price=p,ImageUrl=string.IsNullOrWhiteSpace(image.Text)?null:image.Text.Trim(),CategoryId=cid,Gender=gender.SelectedIndex});else await _api.CreateProductAsync(new CreateProductRequest{Name=name.Text.Trim(),Description=desc.Text.Trim(),Price=p,ImageUrl=string.IsNullOrWhiteSpace(image.Text)?null:image.Text.Trim(),CategoryId=cid,Gender=gender.SelectedIndex,IsFeatured=featured.Checked});DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}